1	package registry
2	
3	import (
4		"errors"
5		"os"
6		"reflect"
7		"testing"
8	)
9	
10	// 本文件为整批转让补充"保存失败"场景的回归保障：业务检查全部通过后，
11	// 在本次内容原子替换已保存数据之前写入失败（原登记册仍可正常读取）时，
12	// 整批必须整体失败、不留任何部分转让，请求号与历史序号都不被消耗；
13	// 保存条件恢复后用完全相同的请求号、原因与条目重提，必须完整执行一次，
14	// 而不是回放一个实际没有保存的成功结果或报请求号冲突。
15	//
16	// 失败注入方式：在临时文件路径 .registry.json.tmp 上预先建一个目录，
17	// save 在 OpenFile 阶段即以 EISDIR 失败——失败发生在 rename 替换
18	// registry.json 之前，原快照完好可读；删除该目录即恢复保存条件。该方式
19	// 不依赖文件权限（root 也生效），也不会触碰原数据文件。
20	
21	// batchSaveFailureReq 是各用例共用的整批请求：至少两件、接收账户互不相同，
22	// 且包含带版税规则的藏品（i1/i3 属 s1：carol 10% + dave 5%；i2 属 s2：
23	// carol 100%）。各件期望持有人 bob、版本 1。
24	func batchSaveFailureReq() TransferBatchRequest {
25		return tbtReq("rb-fail",
26			tbtEntry("i1", "carol", 1, 10000),
27			tbtEntry("i2", "dave", 1, 333),
28			tbtEntry("i3", "alice", 1, 500),
29		)
30	}
31	
32	// seedBatchSaveFailureWorld 建立一个已经存在成功转让与应付记录的登记册：
33	// setupBatchTransferWorld 发行 i1..i5（历史序号 1..5）后，再由 alice 发行
34	// i6（s1，序号 6）给 bob，并由 bob 以 10000 分把 i6 转让给 alice（序号 7）。
35	// 因此失败发生前最后一条历史序号是 7；carol/dave 各有一条序号 7 的应付
36	// （1000/500），余款 8500 归 bob。清单外藏品 i4（bob，版本 1）、i5
37	// （carol，版本 1）与已易手的 i6（alice，版本 2）用于核对失败不外溢。
38	func seedBatchSaveFailureWorld(t *testing.T, r *Registry) {
39		t.Helper()
40		setupBatchTransferWorld(t, r)
41		if _, err := r.Issue(IssueRequest{
42			Operator: "alice", Reason: "首发", RequestID: "ri-i6",
43			ItemID: "i6", SeriesID: "s1", BatchNo: "b1",
44			Metadata: "元-i6", HolderID: "bob",
45		}); err != nil {
46			t.Fatal(err)
47		}
48		if _, err := r.Transfer(TransferRequest{
49			Operator: "bob", Reason: "先存一笔成功转让", RequestID: "rt-prior", ItemID: "i6",
50			ExpectedOwner: "bob", ExpectedVer: 1, ToID: "alice", Price: 10000,
51		}); err != nil {
52			t.Fatal(err)
53		}
54	}
55	
56	// blockBatchSave 让下一次 commit 的写入在替换数据文件之前确定性失败。
57	func blockBatchSave(t *testing.T, r *Registry) {
58		t.Helper()
59		if err := os.MkdirAll(tempFile(r.dir), dirMode); err != nil {
60			t.Fatalf("注入保存失败: %v", err)
61		}
62	}
63	
64	// restoreBatchSave 恢复保存条件：移除占据临时文件路径的目录。
65	func restoreBatchSave(t *testing.T, r *Registry) {
66		t.Helper()
67		if err := os.RemoveAll(tempFile(r.dir)); err != nil {
68			t.Fatalf("恢复保存条件: %v", err)
69		}
70	}
71	
72	// businessSentinels 是保存错误必须有别于业务拒绝的哨兵集合。
73	var businessSentinels = []error{
74		ErrConflict, ErrAccountInactive, ErrSameAccount, ErrForbidden,
75		ErrRequestConflict, ErrInvalidArgument, ErrNotFound, ErrSeriesSealed,
76	}
77	
78	// assertSaveFailureError 确认返回的是保存错误而非任何业务拒绝。
79	func assertSaveFailureError(t *testing.T, err error) {
80		t.Helper()
81		if err == nil {
82			t.Fatal("保存失败必须返回错误，却返回了 nil")
83		}
84		for _, s := range businessSentinels {
85			if errors.Is(err, s) {
86				t.Fatalf("返回的应是保存错误，不能是业务拒绝 %v: %v", s, err)
87			}
88		}
89	}
90	
91	// assertBatchStillPending 在（失败返回后的）同一个已打开登记册上核对：
92	// 整批如同从未发生，且失败前已有的内容、顺序与金额完整保留。
93	func assertBatchStillPending(t *testing.T, r *Registry) {
94		t.Helper()
95		req := batchSaveFailureReq()
96	
97		// 清单内每件仍属原持有人 bob，持有版本没有增加。
98		for _, id := range []string{"i1", "i2", "i3"} {
99			h, err := r.GetHolding(id)
100			if err != nil {
101				t.Fatalf("GetHolding %s: %v", id, err)
102			}
103			if h.OwnerID != "bob" || h.Version != 1 {
104				t.Fatalf("失败后 %s 持有被改变: %+v", id, h)
105			}
106			hist, err := r.History(id)
107			if err != nil {
108				t.Fatalf("History %s: %v", id, err)
109			}
110			if len(hist) != 1 || hist[0].Kind != "issue" {
111				t.Fatalf("失败后 %s 历史多出本次请求: %+v", id, hist)
112			}
113			for _, e := range hist {
114				if e.RequestID == req.RequestID {
115					t.Fatalf("失败后 %s 历史出现请求号 %s: %+v", id, req.RequestID, e)
116				}
117			}
118		}
119	
120		// 历史序号不被消耗：下一条仍是 8（失败前最后一条为 7）。
121		if r.state.NextSeq != 7 {
122			t.Fatalf("NextSeq = %d，失败不应消耗历史序号，仍应为 7", r.state.NextSeq)
123		}
124		// 请求号未被占用：请求记录中没有这一次失败。
125		if _, ok := r.state.Requests[requestKey(req.Operator, req.RequestID)]; ok {
126			t.Fatal("失败的整批不应登记请求结果，请求号应仍可使用")
127		}
128	
129		// 相关收款账户不能多出本次转让的应付明细：旧记录（序号 7）的内容、
130		// 顺序与金额都应保留。
131		wantCarol := []PayableEntry{{TxSeq: 7, ItemID: "i6", Price: 10000, Rate: 1000, Amount: 1000}}
132		wantDave := []PayableEntry{{TxSeq: 7, ItemID: "i6", Price: 10000, Rate: 500, Amount: 500}}
133		carolPay, err := r.PayablesOf("carol")
134		if err != nil {
135			t.Fatal(err)
136		}
137		if !reflect.DeepEqual(carolPay, wantCarol) {
138			t.Fatalf("carol 应付 = %+v, want %+v", carolPay, wantCarol)
139		}
140		davePay, err := r.PayablesOf("dave")
141		if err != nil {
142			t.Fatal(err)
143		}
144		if !reflect.DeepEqual(davePay, wantDave) {
145			t.Fatalf("dave 应付 = %+v, want %+v", davePay, wantDave)
146		}
147	
148		// 失败前那笔成功转让的版税依据与金额原样可读：余款归转让前持有人 bob。
149		tr, err := r.TransferRoyalty(7)
150		if err != nil {
151			t.Fatalf("TransferRoyalty 7: %v", err)
152		}
153		if tr.ItemID != "i6" || tr.Price != 10000 || tr.Remainder != 8500 || tr.OwnerID != "bob" ||
154			len(tr.Payables) != 2 {
155			t.Fatalf("旧转让版税记录被破坏: %+v", tr)
156		}
157	
158		// 清单外藏品的持有与已有记录不受影响。
159		i4, _ := r.GetHolding("i4")
160		if i4.OwnerID != "bob" || i4.Version != 1 {
161			t.Fatalf("清单外 i4 受影响: %+v", i4)
162		}
163		i5, _ := r.GetHolding("i5")
164		if i5.OwnerID != "carol" || i5.Version != 1 {
165			t.Fatalf("清单外 i5 受影响: %+v", i5)
166		}
167		i6, _ := r.GetHolding("i6")
168		if i6.OwnerID != "alice" || i6.Version != 2 {
169			t.Fatalf("清单外 i6 受影响: %+v", i6)
170		}
171		hist6, _ := r.History("i6")
172		if len(hist6) != 2 || hist6[1].Seq != 7 || hist6[1].ToID != "alice" {
173			t.Fatalf("清单外 i6 历史受影响: %+v", hist6)
174		}
175	}
176	
177	// assertBatchRetrySuccess 核对保存恢复后用原请求号重提整批完整执行一次：
178	// 非回放、无请求号冲突；结果按原清单顺序，历史序号紧随失败前最后一条
179	// （7）连续为 8/9/10，每件只增加一个持有版本和一条转让历史，操作者、
180	// 原因与请求号一致；各件金额按自己的价款与所属系列规则计算，余款归
181	// 转让前持有人 bob；按收款账户查询只多出本次真正成功的明细。
182	func assertBatchRetrySuccess(t *testing.T, r *Registry, req TransferBatchRequest) TransferBatchResult {
183		t.Helper()
184		res, err := r.TransferBatch(req)
185		if err != nil {
186			t.Fatalf("保存恢复后用原请求重提应完整执行一次: %v", err)
187		}
188		if res.Replayed {
189			t.Fatal("实际没有保存过成功结果，重提不应是回放，应完整执行一次")
190		}
191		if res.ItemID != "" || res.Err != nil || len(res.Items) != 3 {
192			t.Fatalf("重提结果异常: %+v", res)
193		}
194	
195		type wantItem struct {
196			item, to   string
197			ver, seq   int64
198			price, rem int64
199			payables   []RoyaltyPayable
200		}
201		want := []wantItem{
202			{"i1", "carol", 2, 8, 10000, 8500, []RoyaltyPayable{
203				{AccountID: "carol", Rate: 1000, Amount: 1000},
204				{AccountID: "dave", Rate: 500, Amount: 500},
205			}},
206			{"i2", "dave", 2, 9, 333, 0, []RoyaltyPayable{
207				{AccountID: "carol", Rate: 10000, Amount: 333},
208			}},
209			{"i3", "alice", 2, 10, 500, 425, []RoyaltyPayable{
210				{AccountID: "carol", Rate: 1000, Amount: 50},
211				{AccountID: "dave", Rate: 500, Amount: 25},
212			}},
213		}
214		for i, w := range want {
215			it := res.Items[i]
216			if it.ItemID != w.item || it.FromID != "bob" || it.ToID != w.to ||
217				it.Version != w.ver || it.TxSeq != w.seq ||
218				it.Price != w.price || it.Remainder != w.rem {
219				t.Fatalf("结果第 %d 件 = %+v, want item=%s to=%s ver=%d seq=%d price=%d rem=%d",
220					i, it, w.item, w.to, w.ver, w.seq, w.price, w.rem)
221			}
222			if !reflect.DeepEqual(it.Payables, w.payables) {
223				t.Fatalf("结果第 %d 件 %s 应付 = %+v, want %+v", i, w.item, it.Payables, w.payables)
224			}
225			if i > 0 && it.TxSeq != res.Items[i-1].TxSeq+1 {
226				t.Fatalf("历史序号不连续: %+v", res.Items)
227			}
228	
229			// 每件只增加一个持有版本，且只新增一条属于本次请求的转让历史。
230			h, err := r.GetHolding(w.item)
231			if err != nil {
232				t.Fatal(err)
233			}
234			if h.OwnerID != w.to || h.Version != w.ver {
235				t.Fatalf("成功后 %s 持有 = %+v", w.item, h)
236			}
237			hist, err := r.History(w.item)
238			if err != nil {
239				t.Fatal(err)
240			}
241			if len(hist) != 2 {
242				t.Fatalf("%s 历史应为发行+本次转让两条，得到 %+v", w.item, hist)
243			}
244			last := hist[1]
245			if last.Seq != w.seq || last.Kind != "transfer" ||
246				last.Operator != "bob" || last.Reason != req.Reason || last.RequestID != req.RequestID ||
247				last.FromID != "bob" || last.ToID != w.to ||
248				last.FromVersion != 1 || last.ToVersion != w.ver || last.AuthID != "" {
249				t.Fatalf("%s 本次转让历史 = %+v", w.item, last)
250			}
251			tr, err := r.TransferRoyalty(w.seq)
252			if err != nil {
253				t.Fatalf("TransferRoyalty %d: %v", w.seq, err)
254			}
255			if tr.ItemID != w.item || tr.Price != w.price || tr.Remainder != w.rem ||
256				tr.OwnerID != "bob" || !reflect.DeepEqual(tr.Payables, w.payables) {
257				t.Fatalf("%s 版税记录 = %+v, payables want %+v", w.item, tr, w.payables)
258			}
259		}
260	
261		// 按收款账户查询：只能增加真正成功的三笔（序号 8/9/10）明细，旧的
262		// 序号 7 记录内容、顺序、金额保持不变。
263		wantCarol := []PayableEntry{
264			{TxSeq: 7, ItemID: "i6", Price: 10000, Rate: 1000, Amount: 1000},
265			{TxSeq: 8, ItemID: "i1", Price: 10000, Rate: 1000, Amount: 1000},
266			{TxSeq: 9, ItemID: "i2", Price: 333, Rate: 10000, Amount: 333},
267			{TxSeq: 10, ItemID: "i3", Price: 500, Rate: 1000, Amount: 50},
268		}
269		wantDave := []PayableEntry{
270			{TxSeq: 7, ItemID: "i6", Price: 10000, Rate: 500, Amount: 500},
271			{TxSeq: 8, ItemID: "i1", Price: 10000, Rate: 500, Amount: 500},
272			{TxSeq: 10, ItemID: "i3", Price: 500, Rate: 500, Amount: 25},
273		}
274		if carolPay, err := r.PayablesOf("carol"); err != nil || !reflect.DeepEqual(carolPay, wantCarol) {
275			t.Fatalf("carol 应付 = %+v, err %v, want %+v", carolPay, err, wantCarol)
276		}
277		if davePay, err := r.PayablesOf("dave"); err != nil || !reflect.DeepEqual(davePay, wantDave) {
278			t.Fatalf("dave 应付 = %+v, err %v, want %+v", davePay, err, wantDave)
279		}
280		// alice 只是接收账户，不是任何系列的收款人：不应多出任何明细。
281		if alicePay, err := r.PayablesOf("alice"); err != nil || len(alicePay) != 0 {
282			t.Fatalf("非收款人 alice 应付 = %+v, err %v, 应为空", alicePay, err)
283		}
284	
285		// 最后一条历史序号为 10，8/9/10 连续无空洞（NextSeq 记录最后已分配
286		// 的序号）。
287		if r.state.NextSeq != 10 {
288			t.Fatalf("NextSeq = %d, want 10", r.state.NextSeq)
289		}
290	
291		// 再用完全相同的请求号重提：回放首次成功结果，不再执行第二次。
292		replay, err := r.TransferBatch(req)
293		if err != nil {
294			t.Fatalf("成功后重提应回放: %v", err)
295		}
296		if !replay.Replayed || len(replay.Items) != 3 {
297			t.Fatalf("成功后重提 = %+v", replay)
298		}
299		for i := range want {
300			if replay.Items[i].ItemID != res.Items[i].ItemID ||
301				replay.Items[i].TxSeq != res.Items[i].TxSeq ||
302				replay.Items[i].Version != res.Items[i].Version {
303				t.Fatalf("回放内容与首次成功不一致: %+v vs %+v", replay.Items[i], res.Items[i])
304			}
305			h, _ := r.GetHolding(want[i].item)
306			if h.Version != want[i].ver {
307				t.Fatalf("回放又增加了持有版本: %+v", h)
308			}
309			if hist, _ := r.History(want[i].item); len(hist) != 2 {
310				t.Fatalf("回放又产生了历史: %+v", hist)
311			}
312		}
313		if carolPay, _ := r.PayablesOf("carol"); len(carolPay) != len(wantCarol) {
314			t.Fatalf("回放又产生了应付明细: %+v", carolPay)
315		}
316		return res
317	}
318	
319	// TestTransferBatchSaveFailureSameRegistry 覆盖核心场景：保存失败后调用者
320	// 继续使用同一个已打开的登记册，全部状态停留在整批之前；保存条件恢复后
321	// 用原请求号重提完整执行一次。
322	func TestTransferBatchSaveFailureSameRegistry(t *testing.T) {
323		r := mustCreate(t, tempDir(t))
324		seedBatchSaveFailureWorld(t, r)
325		req := batchSaveFailureReq()
326	
327		// 业务参数完全合规（账户登记可用、接收人不同、期望持有人与版本相符、
328		// 价款非负），失败只可能来自写入阶段。
329		blockBatchSave(t, r)
330		res, err := r.TransferBatch(req)
331		assertSaveFailureError(t, err)
332		if len(res.Items) != 0 || res.ItemID != "" || res.Replayed || res.Err != nil {
333			t.Fatalf("保存失败必须整体失败，不能返回任何一件已转让成功的结果: %+v", res)
334		}
335	
336		// 同一个已打开的登记册上立即查询：整批从未发生，旧记录完整保留。
337		assertBatchStillPending(t, r)
338	
339		// 保存条件恢复后用完全相同的请求号、原因和条目再次提交：原来的期望
340		// 持有人与版本仍然有效，整批完整执行一次（非回放、无请求号冲突）。
341		restoreBatchSave(t, r)
342		assertBatchRetrySuccess(t, r, req)
343	
344		// 清单外藏品在失败与重试之后仍保持原状。
345		i4, _ := r.GetHolding("i4")
346		if i4.OwnerID != "bob" || i4.Version != 1 {
347			t.Fatalf("清单外 i4 最终受影响: %+v", i4)
348		}
349		i5, _ := r.GetHolding("i5")
350		if i5.OwnerID != "carol" || i5.Version != 1 {
351			t.Fatalf("清单外 i5 最终受影响: %+v", i5)
352		}
353		i6, _ := r.GetHolding("i6")
354		if i6.OwnerID != "alice" || i6.Version != 2 {
355			t.Fatalf("清单外 i6 最终受影响: %+v", i6)
356		}
357	}
358	
359	// TestTransferBatchSaveFailureRetryAfterReopen 覆盖磁盘视角：保存失败后
360	// 原登记册仍可正常读取——关闭后重新 Open，看到的仍是整批前状态；此时用
361	// 原请求号重提同样完整执行一次，而不是回放未保存的成功。
362	func TestTransferBatchSaveFailureRetryAfterReopen(t *testing.T) {
363		dir := tempDir(t)
364		r := mustCreate(t, dir)
365		t.Cleanup(func() { _ = r.Close() })
366		seedBatchSaveFailureWorld(t, r)
367		req := batchSaveFailureReq()
368	
369		blockBatchSave(t, r)
370		res, err := r.TransferBatch(req)
371		assertSaveFailureError(t, err)
372		if len(res.Items) != 0 || res.Replayed {
373			t.Fatalf("保存失败必须整体失败: %+v", res)
374		}
375	
376		// 原数据文件从未被替换：正常关闭并重新打开仍能读取整批前的状态。
377		if err := r.Close(); err != nil {
378			t.Fatal(err)
379		}
380		r2, err := Open(dir)
381		if err != nil {
382			t.Fatalf("失败后原登记册必须仍能正常读取: %v", err)
383		}
384		t.Cleanup(func() { _ = r2.Close() })
385		assertBatchStillPending(t, r2)
386	
387		// 恢复保存条件后，在重开的登记册上用原请求重提：完整执行一次。
388		restoreBatchSave(t, r2)
389		assertBatchRetrySuccess(t, r2, req)
390	}
391

