573		}
574		if strings.TrimSpace(req.AuthID) == "" {
575			missing = append(missing, "auth_id")
576		}
577		if strings.TrimSpace(req.ItemID) == "" {
578			missing = append(missing, "item_id")
579		}
580		if strings.TrimSpace(req.TrusteeID) == "" {
581			missing = append(missing, "trustee_id")
582		}
583		if strings.TrimSpace(req.ToID) == "" {
584			missing = append(missing, "to_id")
585		}
586		if strings.TrimSpace(req.ExpectedOwner) == "" {
587			missing = append(missing, "expected_owner")
588		}
589		if req.ExpectedVer <= 0 {
