604	func createAuthzParamsSig(req CreateAuthorizationRequest) string {
605		// Price 用 omitempty：价款为 0 时签名与旧格式一致，旧授权创建请求
606		// 仍可回放；改价则按请求号冲突拒绝。
607		b, _ := json.Marshal(struct {
608			Kind          string `json:"kind"`
609			AuthID        string `json:"auth_id"`
610			ItemID        string `json:"item_id"`
611			TrusteeID     string `json:"trustee_id"`
612			ToID          string `json:"to_id"`
613			ExpectedOwner string `json:"expected_owner"`
614			ExpectedVer   int64  `json:"expected_version"`
615			ExpiresAt     string `json:"expires_at"`
616			Price         int64  `json:"price,omitempty"`
617			Reason        string `json:"reason"`
618		}{"auth_create", req.AuthID, req.ItemID, req.TrusteeID, req.ToID,
619			req.ExpectedOwner, req.ExpectedVer,
620			req.ExpiresAt.UTC().Format(time.RFC3339Nano), req.Price, req.Reason})
621		return string(b)
622	}
