72	func TestTransferBatchSuccess(t *testing.T) {
73		r := mustCreate(t, tempDir(t))
74		setupBatchTransferWorld(t, r)
75	
76		req := tbtReq("rt1",
77			tbtEntry("i1", "carol", 1, 10000),
78			tbtEntry("i2", "dave", 1, 333),
79			tbtEntry("i3", "carol", 1, 0), // 未填价款按零；接收账户 carol 重复
80			tbtEntry("i4", "alice", 1, 500),
81		)
82		res, err := r.TransferBatch(req)
83		if err != nil {
84			t.Fatalf("TransferBatch: %v", err)
85		}
86		if res.Replayed || res.Err != nil || res.ItemID != "" {
87			t.Fatalf("unexpected result flags: %+v", res)
88		}
89		if len(res.Items) != 4 {
90			t.Fatalf("want 4 items, got %d", len(res.Items))
91		}
92	
93		// 历史序号连续递增，且紧随发行序号之后。
94		for i, it := range res.Items {
95			if it.TxSeq != int64(6+i) {
96				t.Errorf("item %d TxSeq = %d, want %d", i, it.TxSeq, 6+i)
97			}
98			if i > 0 && it.TxSeq != res.Items[i-1].TxSeq+1 {
99				t.Fatalf("TxSeq not consecutive: %+v", res.Items)
100			}
101		}
102	
103		want := []struct {
104			item, from, to string
105			ver            int64
106			price, rem     int64
107			payees         []RoyaltyPayable
108		}{
109			{"i1", "bob", "carol", 2, 10000, 8500, []RoyaltyPayable{
110				{AccountID: "carol", Rate: 1000, Amount: 1000},
111				{AccountID: "dave", Rate: 500, Amount: 500},
112			}},
113			{"i2", "bob", "dave", 2, 333, 0, []RoyaltyPayable{
114				{AccountID: "carol", Rate: 10000, Amount: 333},
115			}},
116			{"i3", "bob", "carol", 2, 0, 0, []RoyaltyPayable{
117				{AccountID: "carol", Rate: 1000, Amount: 0}, // 零金额明细保留
118				{AccountID: "dave", Rate: 500, Amount: 0},
119			}},
120			{"i4", "bob", "alice", 2, 500, 500, nil}, // 无版税规则：无明细，余款为全款
121		}
122		for i, w := range want {
123			it := res.Items[i]
124			if it.ItemID != w.item || it.FromID != w.from || it.ToID != w.to ||
125				it.Version != w.ver || it.Price != w.price || it.Remainder != w.rem {
126				t.Errorf("item %d = %+v", i, it)
127			}
128			if len(it.Payables) != len(w.payees) {
129				t.Errorf("item %s payables = %+v, want %+v", w.item, it.Payables, w.payees)
130				continue
131			}
132			for j := range w.payees {
133				if it.Payables[j] != w.payees[j] {
134					t.Errorf("item %s payable %d = %+v, want %+v", w.item, j, it.Payables[j], w.payees[j])
135				}
136			}
137		}
138	
139		// 各件通过现有持有、历史、应付查询核对；历史保留整批共用的操作者、
140		// 原因与请求号，且不带授权编号。
141		for _, w := range want {
142			h, err := r.GetHolding(w.item)
143			if err != nil {
144				t.Fatalf("GetHolding %s: %v", w.item, err)
145			}
146			if h.OwnerID != w.to || h.Version != w.ver {
147				t.Errorf("holding %s = %+v", w.item, h)
148			}
149			hist, err := r.History(w.item)
150			if err != nil {
151				t.Fatalf("History %s: %v", w.item, err)
152			}
153			if len(hist) != 2 {
154				t.Fatalf("history %s = %+v", w.item, hist)
155			}
156			last := hist[1]
157			if last.Kind != "transfer" || last.Operator != "bob" || last.Reason != "整批转出" ||
158				last.RequestID != "rt1" || last.FromID != "bob" || last.ToID != w.to ||
159				last.FromVersion != 1 || last.ToVersion != w.ver || last.AuthID != "" {
160				t.Errorf("history entry %s = %+v", w.item, last)
161			}
162			tr, err := r.TransferRoyalty(last.Seq)
163			if err != nil {
164				t.Fatalf("TransferRoyalty %d: %v", last.Seq, err)
165			}
166			if tr.ItemID != w.item || tr.Price != w.price || tr.Remainder != w.rem ||
167				tr.OwnerID != "bob" {
168				t.Errorf("royalty %s = %+v", w.item, tr)
169			}
170		}
171	
172		// 同一收款账户在多件中出现分别保留明细，不合并价款。
173		carolPay, err := r.PayablesOf("carol")
174		if err != nil {
175			t.Fatal(err)
176		}
177		if len(carolPay) != 3 {
178			t.Fatalf("carol payables = %+v, want 3 separate lines", carolPay)
179		}
180		gotAmounts := map[int64]int64{}
181		for _, p := range carolPay {
182			gotAmounts[p.TxSeq] = p.Amount
183		}
184		if gotAmounts[6] != 1000 || gotAmounts[7] != 333 || gotAmounts[8] != 0 {
185			t.Fatalf("carol payable amounts = %+v", gotAmounts)
186		}
187		davePay, err := r.PayablesOf("dave")
188		if err != nil {
189			t.Fatal(err)
190		}
191		if len(davePay) != 2 || davePay[0].Amount != 500 || davePay[1].Amount != 0 {
192			t.Fatalf("dave payables = %+v", davePay)
193		}
194	}
