411	// ---- 幂等回放与请求号冲突 ----
412	
413	func TestTransferBatchIdempotency(t *testing.T) {
414		r := mustCreate(t, tempDir(t))
415		setupBatchTransferWorld(t, r)
416	
417		req := tbtReq("rb1", tbtEntry("i1", "carol", 1, 10000), tbtEntry("i2", "dave", 1, 333))
418		first, err := r.TransferBatch(req)
419		if err != nil {
420			t.Fatalf("first: %v", err)
421		}
422	
423		// 完全相同的内容与顺序重提：回放首次成功结果。
424		second, err := r.TransferBatch(req)
425		if err != nil {
426			t.Fatalf("replay: %v", err)
427		}
428		if !second.Replayed || second.ItemID != "" {
429			t.Fatalf("replay flags = %+v", second)
430		}
431		if len(second.Items) != len(first.Items) {
432			t.Fatalf("items = %+v", second.Items)
433		}
434		for i := range first.Items {
435			if !reflect.DeepEqual(second.Items[i], first.Items[i]) {
436				t.Errorf("item %d: replay %+v != first %+v", i, second.Items[i], first.Items[i])
437			}
438		}
439		for _, id := range []string{"i1", "i2"} {
440			hist, err := r.History(id)
441			if err != nil {
442				t.Fatal(err)
443			}
444			if len(hist) != 2 {
445				t.Fatalf("%s history changed on replay: %+v", id, hist)
446			}
447		}
448	
449		// 改动原因、条目顺序或任一条目参数都是请求号冲突。
450		mutations := map[string]TransferBatchRequest{
451			"改原因":   {Operator: "bob", Reason: "别的原因", RequestID: "rb1", Entries: req.Entries},
452			"改顺序":   tbtReq("rb1", tbtEntry("i2", "dave", 1, 333), tbtEntry("i1", "carol", 1, 10000)),
453			"改价款":   tbtReq("rb1", tbtEntry("i1", "carol", 1, 9999), tbtEntry("i2", "dave", 1, 333)),
454			"改接收人":  tbtReq("rb1", tbtEntry("i1", "dave", 1, 10000), tbtEntry("i2", "dave", 1, 333)),
455			"改期望版本": tbtReq("rb1", tbtEntry("i1", "carol", 2, 10000), tbtEntry("i2", "dave", 1, 333)),
456			"改期望持有人": func() TransferBatchRequest {
457				q := tbtReq("rb1", tbtEntry("i1", "carol", 1, 10000), tbtEntry("i2", "dave", 1, 333))
458				q.Entries[0].ExpectedOwner = "alice"
459				return q
460			}(),
461		}
462		for name, m := range mutations {
463			if _, err := r.TransferBatch(m); !errors.Is(err, ErrRequestConflict) {
464				t.Errorf("%s: err = %v, want ErrRequestConflict", name, err)
465			}
466		}
467	
468		// 与已有操作共用请求号：单件转让用过的号不能用于整批。
469		if _, err := r.Transfer(TransferRequest{
470			Operator: "bob", Reason: "卖出", RequestID: "shared", ItemID: "i3",
471			ExpectedOwner: "bob", ExpectedVer: 1, ToID: "alice",
472		}); err != nil {
473			t.Fatal(err)
474		}
475		if _, err := r.TransferBatch(tbtReq("shared", tbtEntry("i4", "carol", 1, 0))); !errors.Is(err, ErrRequestConflict) {
476			t.Fatalf("request id shared with single transfer: %v", err)
477		}
478	}
