		t.Fatalf("操作者账户错误不附藏品编号: %+v", res)
	}
	// 再次重提回放已保存的拒绝，仍不带藏品编号。
	replay, err := r.TransferBatch(req)
	if !errors.Is(err, ErrAccountInactive) || !replay.Replayed || replay.ItemID != "" {
		t.Fatalf("应回放操作者停用拒绝: %+v %v", replay, err)
