	advanceI1ToBobVer9(t, r2)
	res, err = r2.TransferBatch(req)
	if err != nil || res.Replayed || len(res.Items) != 1 {
		t.Fatalf("重开后状态合法的原请求应完整执行一次: %+v %v", res, err)
	}
	if w := res.Items[0]; w.ToID != "carol" || w.Version != 10 {
		t.Fatalf("执行结果异常: %+v", w)
